#include <stdio.h>

static long long factorial(int n)
{
    if (n <= 1)
        return 1;
    return (long long)n * factorial(n - 1);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0 || n > 20)
        return 0;

    printf("%lld\n", factorial(n));
    return 0;
}

