#include <stdio.h>

static int bin_search(const int *a, int lo, int hi, int target, int *cnt)
{
    int mid;

    if (lo > hi)
        return -1;

    mid = lo + (hi - lo) / 2;
    (*cnt)++;

    if (a[mid] == target)
        return mid;
    if (a[mid] < target)
        return bin_search(a, mid + 1, hi, target, cnt);
    return bin_search(a, lo, mid - 1, target, cnt);
}

int main(void)
{
    static int a[100000];
    int n, target, i, cnt = 0, idx;

    if (scanf("%d %d", &n, &target) != 2 || n <= 0 || n > 100000)
        return 0;

    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    idx = bin_search(a, 0, n - 1, target, &cnt);
    printf("%d\n%d\n", idx, cnt);
    return 0;
}

