#include <stdio.h>

/* static 局部变量：只初始化一次，跨调用保持累计值 */
static long long call_count(int add)
{
    static long long calls = 0;

    if (add)
        ++calls;
    return calls;
}

static long long fib(int n)
{
    call_count(1);
    if (n <= 2)
        return 1;
    return fib(n - 1) + fib(n - 2);
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 1 || n > 25)
        return 0;

    printf("%lld\n", fib(n));
    printf("%lld\n", call_count(0));
    return 0;
}

