#include <stdio.h>

/* 值传递：形参是实参的副本，交换形参不影响调用者 */
static void swap_value(int x, int y)
{
    int t = x;
    x = y;
    y = t;
}

/* 地址传递：通过指针修改调用者的存储单元 */
static void swap_addr(int *x, int *y)
{
    int t = *x;
    *x = *y;
    *y = t;
}

int main(void)
{
    int a, b;

    if (scanf("%d %d", &a, &b) != 2)
        return 0;

    swap_value(a, b);
    printf("%d %d\n", a, b);

    swap_addr(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}

