#include <stdio.h>

static int n;
static int a[8], used[8], path[8];

static void dfs(int depth)
{
    int i;

    if (depth == n) {
        for (i = 0; i < n; i++)
            printf("%d%c", path[i], i + 1 < n ? ' ' : '\n');
        return;
    }

    for (i = 0; i < n; i++) {
        if (!used[i]) {
            used[i] = 1;
            path[depth] = a[i];
            dfs(depth + 1);
            used[i] = 0;
        }
    }
}

int main(void)
{
    int i, j, t;

    if (scanf("%d", &n) != 1 || n < 1 || n > 8)
        return 0;

    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    /* 插入排序，保证按字典序输出 */
    for (i = 1; i < n; i++) {
        t = a[i];
        for (j = i - 1; j >= 0 && a[j] > t; j--)
            a[j + 1] = a[j];
        a[j + 1] = t;
    }

    dfs(0);
    return 0;
}

