#include <stdio.h>

static int n;
static char buf[17];   /* 最多 2 * 8 个字符，再加结束符 */

static void dfs(int pos, int open_cnt, int close_cnt)
{
    if (pos == 2 * n) {
        buf[pos] = '\0';
        printf("%s\n", buf);
        return;
    }

    if (open_cnt < n) {
        buf[pos] = '(';
        dfs(pos + 1, open_cnt + 1, close_cnt);
    }

    if (close_cnt < open_cnt) {
        buf[pos] = ')';
        dfs(pos + 1, open_cnt, close_cnt + 1);
    }
}

int main(void)
{
    if (scanf("%d", &n) != 1 || n < 1 || n > 8)
        return 0;

    dfs(0, 0, 0);
    return 0;
}

