#include <iostream>
#include <string>

static int n;
static std::string buf;

static void dfs(int pos, int open_cnt, int close_cnt)
{
    if (pos == 2 * n) {
        std::cout << buf << '\n';
        return;
    }

    if (open_cnt < n) {
        buf.push_back('(');
        dfs(pos + 1, open_cnt + 1, close_cnt);
        buf.pop_back();
    }

    if (close_cnt < open_cnt) {
        buf.push_back(')');
        dfs(pos + 1, open_cnt, close_cnt + 1);
        buf.pop_back();
    }
}

